mapper.select:
select `d`.*,ud.real_name as doctor_real_name, u.real_name, o.order_number, dd.drug_name from `diagnose` d   left join `user` ud on d.doctor_user_id = ud.id
   left join `user` u on d.user_id = u.id
   left join `order` o on d.order_id = o.id
   left join `drug` dd on d.drug_id = dd.id
   where 1=1
    
        and d.doctor_user_id = #{doctorUserId}
    
    
        and d.user_id = #{userId}
    
    
        and d.order_id = #{orderId}
    
    
        and d.drug_id = #{drugId}
    
    
        and ud.real_name like concat('%',#{doctorRealName},'%')
    
            
        and u.real_name like concat('%',#{realName},'%')
    
            
        and o.order_number like concat('%',#{orderNumber},'%')
    
            
        and dd.drug_name like concat('%',#{drugName},'%')
